functions.source_context:
def source_context(require_frozen):
    config = json.loads(INPUTS.read_text())
    require(config.get("schema") == OBSERVATION_SCHEMA, "Wrong observation schema")
    require(config["selected_case_ids"] == SELECTED, "The exact two original additive cases are required")
    head = git("rev-parse", "HEAD")
    source = config["application_source_sha"]
    trees = {p: git("rev-parse", "HEAD:" + p) for p in ("Source", "Vendor", "Maktabah.xcodeproj", "Maktabah-iOSUITests")}
    if require_frozen:
        require(re.fullmatch(r"[0-9a-f]{40}", source) is not None, "Application source is UNFINALIZED")
        require(head == os.environ.get("EXPECTED_CHECKOUT_SHA"), "Wrong immutable checkout")
        require(command(["git", "merge-base", "--is-ancestor", source, head], check=False).returncode == 0,
                "Frozen application source is not an ancestor")
        require(trees == config["application_trees"], "Actual compiled source/test trees differ from frozen inputs")
        require(all(git("rev-parse", source + ":" + p) == value for p, value in trees.items()), "Frozen tree drift")
    records = {}
    for path in config["execution_input_paths"]:
        local = ROOT / path
        require(local.is_file() and not local.is_symlink(), "Missing exact execution input: " + path)
        data = local.read_bytes()
        records[path] = {"bytes": len(data), "sha256": hashlib.sha256(data).hexdigest()}
        if require_frozen:
            expected = config["input_sha256"].get(path)
            require(expected is not None and records[path]["sha256"] == expected, "Execution byte pin changed: " + path)
            require(command(["git", "hash-object", str(local)]).stdout.strip() == git("rev-parse", "HEAD:" + path),
                    "Dirty committed execution input: " + path)
    return {"checkout_sha": head, "application_source_sha": source, "application_trees": trees,
            "inputs_file_sha256": digest(INPUTS), "execution_inputs": records,
            "scope": "Debug original production-corpus UI observation; no final Native116/Release114/device acceptance"}

functions.verify_actual_sources:
def verify_actual_sources(report):
    entries = subprocess.check_output(["git", "ls-tree", "-r", "-z", "HEAD", "--", "Source", "Vendor"], cwd=ROOT)
    expected = {}
    for entry in entries.split(b"\0"):
        if not entry:
            continue
        meta, path = entry.split(b"\t", 1)
        if meta.split()[1] == b"blob":
            expected[path.decode()] = meta.split()[2].decode()
    paths = list(expected)
    actual = subprocess.check_output(["git", "hash-object", "--no-filters", "--stdin-paths"], cwd=ROOT,
                                     input=("\n".join(paths) + "\n").encode()).decode().splitlines()
    require(len(actual) == len(paths), "Actual source hash inventory incomplete")
    mismatches = [path for path, blob in zip(paths, actual) if blob != expected[path]]
    if "Source/PrivacyInfo.xcprivacy" in mismatches:
        audit_generated_privacy(report, expected["Source/PrivacyInfo.xcprivacy"])
        mismatches.remove("Source/PrivacyInfo.xcprivacy")
    require(not mismatches, "Dependency setup changed tracked app input: " + ", ".join(mismatches[:10]))
    report["actual_source_inputs_verified"] = len(paths)
    (OUT / "actual-source-inputs.json").write_text(json.dumps(dict(zip(paths, actual)), indent=2) + "\n")
    checkouts = ROOT / "build/SourcePackages/checkouts"
    folders = {p.name.casefold(): p for p in checkouts.iterdir() if p.is_dir()}
    report["actual_package_checkouts"] = {}
    for identity, revision in report["package_pins"].items():
        require(identity.casefold() in folders, "Pinned package checkout missing: " + identity)
        folder = folders[identity.casefold()]
        head = capture("git", "-C", str(folder), "rev-parse", "HEAD")
        dirty = capture("git", "-C", str(folder), "status", "--porcelain")
        require(head == revision and not dirty, "Pinned package source differs/dirty: " + identity)
        report["actual_package_checkouts"][identity] = {"head": head, "status": "CLEAN"}

functions.code_images:
def code_images(root):
    result, required = {}, []
    magic = {b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe", b"\xfe\xed\xfa\xce", b"\xfe\xed\xfa\xcf",
             b"\xca\xfe\xba\xbe", b"\xbe\xba\xfe\xca", b"\xca\xfe\xba\xbf", b"\xbf\xba\xfe\xca"}
    for name in PRODUCT_PATHS:
        bundle = root / name
        info = plistlib.loads((bundle / "Info.plist").read_bytes())
        required.append((bundle / info["CFBundleExecutable"]).relative_to(root).as_posix())
        for path in bundle.rglob("*"):
            require(not path.is_symlink(), "Prior native product contains an unexpected alias")
            if not path.is_file():
                continue
            with path.open("rb") as stream:
                header = stream.read(8)
            if header[:4] in magic or header == b"!<arch>\n":
                result[path.relative_to(root).as_posix()] = record(path)
    require(all(path in result for path in required), "Prior original app/UI-runner images are absent")
    return result
